grid = [[1]*13 for _ in range(21)]
anchors=[(2,6),(2,10),(4,3),(7,6),(7,10),(10,1),(10,9),(17,2),(17,9)]
# Seed's 3x3 footprint, anchored where the seed's center 3 at (r14,c6) lands on each marker.
pattern={(-1,-2):3,(-1,-1):5,(-1,0):3,(0,-1):5,(0,0):3,(1,0):3}
# Original seed (not modified by stamping)
for r,c,v in [(13,4,3),(13,5,5),(13,6,3),(14,5,5),(14,6,3),(15,6,3)]: grid[r][c]=v
for ar,ac in anchors:
    for (dr,dc),v in pattern.items():
        r,c=ar+dr,ac+dc
        if 0 <= r < 21 and 0 <= c < 13:
            # Only the marker at motif-center and background cells are overwritten.
            if (r,c)==(ar,ac) or grid[r][c]==1:
                grid[r][c]=v
print(len(grid), sorted(set(map(len,grid))))
print(''.join(' '+str(len(row)) for row in grid))
print(__import__('json').dumps(grid,separators=(',',':')))

import json
G=[[1]*13 for _ in range(21)]
# Preserve the observed 3x3 seed, including background cells in its footprint.
seed=[[3,5,3],[1,5,3],[1,1,3]]
for r in range(3):
    for c in range(3): G[13+r][4+c]=seed[r][c]
anchors=[(2,6),(2,10),(4,3),(7,6),(7,10),(10,1),(10,9),(17,2),(17,9)]
# Geometrically center the full 3x3 motif on each 8 marker; center seed color is 5.
for ar,ac in anchors:
    for dr in range(-1,2):
        for dc in range(-1,2):
            r,c=ar+dr,ac+dc
            if 0<=r<21 and 0<=c<13:
                G[r][c]=seed[dr+1][dc+1]
assert len(G)==21 and all(len(row)==13 for row in G)
print(json.dumps(G,separators=(',',':')))

